// Bounded private UNIX-socket mock accounting. No model/backend headers/libs.
#include "accounting_ipc.hpp"
#include "launch_gate.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sys/wait.h>
using namespace hs::n1chain;
namespace fs=std::filesystem;
static unsigned groups=0;
static void check(bool b,const char*m){require(b,m);}
template<class F>static void rejects(F f){bool b=false;try{f();}catch(const std::exception&){b=true;}check(b,"expected accounting failure");}
static void make_dir(const std::string&p){checked(::mkdir(p.c_str(),0700),"fresh private CPU fixture directory");}
static MockBudgetConfig budget_config(){MockBudgetConfig c;c.run_id="CPU-MOCK-ONE-GLOBAL-LEDGER";c.source_sha256=std::string(64,'a');c.deadline_epoch=IO{}.wall()+20;c.limits={{"requests",2},{"rows",2},{"backend_inits",2},{"models",2},{"contexts",2},{"placements",2}};c.request_rows={{"a",1},{"b",1}};return c;}
static BrokerConfig broker_config(const MockBudgetConfig&c){BrokerConfig p;p.mode="CPU_MOCK_ONLY";p.run_id=c.run_id;p.manifest_sha256=Sha256::of(c.canonical());p.clients={{"worker1",{{"a"},{"deploy1"},"CPU_MOCK_ONLY",""}},{"worker2",{{"b"},{"deploy2"},"CPU_MOCK_ONLY",""}}};p.max_commands=64;p.idle_timeout_ms=800;p.total_timeout_ms=5000;return p;}
struct Child{pid_t pid;std::string dir,socket;MockBudgetConfig cfg;};
static Child launch(const std::string&root,const std::string&name,MockBudgetConfig cfg,int fault=0,int preexec=0){
 const auto dir=root+"/"+name;make_dir(dir);const auto sock=dir+"/s";check(sock.size()<sizeof(sockaddr_un{}.sun_path),"short private socket path required");const auto pid=::fork();checked(pid,"fork bounded CPU mock broker");
 if(pid==0){int exit_code=90;try{DurableMockBudget b(dir+"/ledger",cfg);auto policy=broker_config(cfg);if(preexec){policy.clients={{"launch1",{{},{"deploy1"},"LAUNCH_ONLY",""}},{"worker1",{{"a"},{"deploy1"},"WORKER","launch1"}}};if(preexec==2){policy.clients["launch2"]={{},{"deploy2"},"LAUNCH_ONLY",""};policy.clients["worker2"]={{"b"},{"deploy2"},"WORKER","launch2"};}}ipc::SocketIO io;bool truncated=false;
   io.send=[&](int f,const void*p,std::size_t n)->ssize_t{
    const auto*s=static_cast<const char*>(p);
    if(fault==2&&n>=5&&std::string(s,5)=="ACK\t1")::_exit(91); // durable request consumed, no ACK
    if(fault==1&&n>=5&&std::string(s,5)=="ACK\t2"){truncated=true;return::send(f,p,3,MSG_NOSIGNAL);}
    if(truncated){errno=EPIPE;return-1;}return::send(f,p,n,MSG_NOSIGNAL);
   };
   AccountingBroker broker(sock,b,policy,io);auto r=broker.run();std::ofstream out(dir+"/BROKER_RESULT.json");out<<"{\"complete\":"<<(r.complete?"true":"false")<<",\"commands\":"<<r.commands<<",\"clients\":"<<r.clients<<",\"native_authority\":false}\n";out.close();exit_code=r.complete?0:17;
  }catch(const std::exception&e){std::ofstream(dir+"/BROKER_ERROR.txt")<<e.what()<<'\n';}::_exit(exit_code);
 }
 const auto until=ipc::deadline(2000);for(;;){struct stat s{};if(::lstat(sock.c_str(),&s)==0&&S_ISSOCK(s.st_mode))break;check(ipc::Clock::now()<until,"CPU mock broker did not become ready");::poll(nullptr,0,1);}
 return{pid,dir,sock,std::move(cfg)};
}
static int finish(const Child&c){int s=0;checked(::waitpid(c.pid,&s,0),"wait owned CPU mock broker");check(WIFEXITED(s),"mock broker signal exit");return WEXITSTATUS(s);}
static NativeAccountingClient client(const Child&c,const std::string&id){return NativeAccountingClient(c.socket,c.cfg.run_id,Sha256::of(c.cfg.canonical()),id,1000);}
static void completed_worker(const Child&c,const std::string&worker,const std::string&deployment,const std::string&request){auto b=client(c,worker);b.before_backend_init(deployment);b.before_model_load(deployment);b.before_context(deployment);b.before_placement(deployment);b.before_request(request);b.before_decode(request,1);b.finish_request(request,"COMPLETED");b.close_worker();}
static FD raw_client(const Child&c){FD f(::socket(AF_UNIX,SOCK_STREAM|SOCK_CLOEXEC,0));checked(f.n,"raw CPU fixture socket");const auto a=ipc::address(c.socket);checked(::connect(f.n,reinterpret_cast<const sockaddr*>(&a),sizeof a),"raw CPU fixture connect");checked(::fcntl(f.n,F_SETFL,O_NONBLOCK),"nonblocking raw fixture");return f;}
static void hello(int f,const Child&c){ipc::SocketIO io;const auto sha=Sha256::of(c.cfg.canonical());ipc::send_frame(f,"HELLO\t1\t"+hex(c.cfg.run_id)+"\t"+sha+"\t"+hex("worker1"),ipc::deadline(1000),io);check(ipc::frame(f,ipc::deadline(1000))==ipc::ack(0,sha),"raw fixture handshake");}
int main(int argc,char**argv){try{
 require(argc==3&&std::string(argv[1])=="--cpu-mock-ipc-selftest","explicit CPU-only IPC mock mode required");const std::string root=argv[2];check(!root.empty()&&root[0]=='/',"absolute fresh fixture root");make_dir(root);
 auto test=[&](const char*name,auto body){body();groups++;std::cout<<"PASS "<<name<<'\n';};
 test("two separate clients spend one global request/row/deployment ledger",[&]{auto c=launch(root,"ok",budget_config());completed_worker(c,"worker1","deploy1","a");completed_worker(c,"worker2","deploy2","b");check(finish(c)==0,"global mock coordinator did not seal");const auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);for(const auto&x:r.state.counts)check(x.second==2,"global counters reset per worker");check(!r.execution_authorized,"accounting granted native authority");rejects([&]{DurableMockBudget b(c.dir+"/ledger",c.cfg);});});
 test("second worker cannot evade aggregate row cap with a new process",[&]{auto cfg=budget_config();cfg.limits["rows"]=1;auto c=launch(root,"rows",cfg);completed_worker(c,"worker1","deploy1","a");{auto b=client(c,"worker2");b.before_request("b");rejects([&]{b.before_decode("b",1);});check(b.poisoned(),"rejected/lost ACK client not poisoned");rejects([&]{b.before_request("b");});}check(finish(c)==17,"row overrun was not terminal");auto r=DurableMockBudget::inspect(c.dir+"/ledger",cfg);check(r.state.counts.at("rows")==1&&r.state.counts.at("requests")==2,"row rejection refunded/reset aggregate");});
 test("model/context/backend/placement ceilings are shared too",[&]{auto cfg=budget_config();cfg.limits["contexts"]=1;auto c=launch(root,"contexts",cfg);completed_worker(c,"worker1","deploy1","a");{auto b=client(c,"worker2");rejects([&]{b.before_context("deploy2");});}check(finish(c)==17,"context cap was bypassed");auto r=DurableMockBudget::inspect(c.dir+"/ledger",cfg);check(r.state.counts.at("contexts")==1,"context reservation reset");});
 test("partial lost ACK keeps reservation and forbids retry/reconnect",[&]{auto c=launch(root,"ack",budget_config(),1);{auto b=client(c,"worker1");b.before_request("a");rejects([&]{b.before_decode("a",1);});check(b.poisoned(),"partial ACK not terminal");rejects([&]{b.before_decode("a",1);});}check(finish(c)==17,"lost ACK did not stop broker");auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);check(r.state.counts.at("rows")==1&&r.state.active=="a"&&!r.execution_authorized,"unknown work reservation lost");});
 test("broker crash after durable request before ACK is inspection-only",[&]{auto c=launch(root,"crash",budget_config(),2);{auto b=client(c,"worker1");rejects([&]{b.before_request("a");});check(b.poisoned(),"crash ACK unknown not terminal");}check(finish(c)==91,"expected mock crash point missing");auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);check(r.state.counts.at("requests")==1&&r.state.active=="a"&&r.status.find("UNCLEAN")==0,"crash spend/reentry lost");rejects([&]{DurableMockBudget b(c.dir+"/ledger",c.cfg);});});
 test("duplicate worker handshake cannot reconnect under another process",[&]{auto c=launch(root,"reentry",budget_config());completed_worker(c,"worker1","deploy1","a");rejects([&]{auto again=client(c,"worker1");});check(finish(c)==17,"worker reentry permitted");});
 test("run and manifest handshake mismatch stops before work",[&]{auto c=launch(root,"manifest",budget_config());rejects([&]{NativeAccountingClient b(c.socket,c.cfg.run_id,std::string(64,'f'),"worker1",1000);});check(finish(c)==17,"manifest mismatch not terminal");check(DurableMockBudget::inspect(c.dir+"/ledger",c.cfg).state.counts.at("requests")==0,"mismatched handshake consumed model request");});
 test("cross-worker request assignment is rejected",[&]{auto c=launch(root,"scope",budget_config());{auto b=client(c,"worker1");rejects([&]{b.before_request("b");});}check(finish(c)==17,"cross-worker request permitted");});
 test("partial frame and unexpected disconnect stop globally",[&]{auto c=launch(root,"partial",budget_config());{auto f=raw_client(c);hello(f.n,c);uint32_t n=htonl(100);check(::send(f.n,&n,4,MSG_NOSIGNAL)==4,"partial header write");check(::send(f.n,"CMD",3,MSG_NOSIGNAL)==3,"partial body write");}check(finish(c)==17,"partial command not terminal");check(DurableMockBudget::inspect(c.dir+"/ledger",c.cfg).state.counts.at("requests")==0,"partial frame granted work");});
 test("private socket path and actual peer UID are enforced",[&]{int pair[2];checked(::socketpair(AF_UNIX,SOCK_STREAM|SOCK_CLOEXEC,0,pair),"private peer fixture");FD a(pair[0]),b(pair[1]);ipc::peer_uid(a.n,::geteuid());rejects([&]{ipc::peer_uid(a.n,::geteuid()+1);});const auto path=root+"/public";make_dir(path);checked(::chmod(path.c_str(),0755),"public fixture mode");rejects([&]{ipc::private_path(path+"/s");});});
 test("finite idle deadline stops absent next worker without new STATE",[&]{auto c=launch(root,"idle",budget_config());completed_worker(c,"worker1","deploy1","a");check(finish(c)==17,"idle broker ran indefinitely");auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);check(r.state.counts.at("requests")==1&&r.status.find("UNCLEAN")==0,"idle expiry lost global state");});
 test("native worker handshake without completed pre-exec reservation is rejected",[&]{auto c=launch(root,"no-launch",budget_config(),0,true);rejects([&]{auto b=client(c,"worker1");});check(finish(c)==17,"worker crossed before-exec placement gate");check(DurableMockBudget::inspect(c.dir+"/ledger",c.cfg).state.counts.at("placements")==0,"missing launch created placement");});
 test("launch reserves placement once and worker verifies rather than recharges",[&]{auto c=launch(root,"preexec",budget_config(),0,true);{auto b=client(c,"launch1");b.before_placement("deploy1");b.close_worker();}completed_worker(c,"worker1","deploy1","a");check(finish(c)==0,"pre-exec mock handoff failed");auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);check(r.state.counts.at("placements")==1&&r.state.counts.at("contexts")==1,"worker doublecharged or bypassed placement");});
 test("launch cannot close or admit a worker without reserving placement",[&]{auto c=launch(root,"unreserved-launch",budget_config(),0,true);{auto b=client(c,"launch1");rejects([&]{b.close_worker();});}check(finish(c)==17,"unreserved launch accepted");check(DurableMockBudget::inspect(c.dir+"/ledger",c.cfg).state.counts.at("placements")==0,"unreserved launch charged as completed");});
 test("two strict launch-worker pairs still share only one global ledger",[&]{auto c=launch(root,"strict-global",budget_config(),0,2);for(int i=1;i<=2;i++){const auto suffix=std::to_string(i);{auto b=client(c,"launch"+suffix);b.before_placement("deploy"+suffix);b.close_worker();}completed_worker(c,"worker"+suffix,"deploy"+suffix,i==1?"a":"b");}check(finish(c)==0,"strict launch worker pairs failed");auto r=DurableMockBudget::inspect(c.dir+"/ledger",c.cfg);for(const auto&x:r.state.counts)check(x.second==2,"strict global counter duplicated or reset");});
 test("concrete production launch gate stops before IPC and exec callback",[]{ProductionGate g;unsigned execs=0;LaunchAccountingSpec no_connection;rejects([&]{guarded_native_launch(g,no_connection,"native-worker",[&]{execs++;return 0;});});check(execs==0,"native ELF callback reached");});
 test("provided synthetic journal beyond64MiB streams without granting authority",[&]{
  const auto dir=root+"/large-provided-journal";auto cfg=budget_config();{DurableMockBudget b(dir,cfg);b.before_request("a");}
  std::ifstream in(dir+"/ledger.tsv",std::ios::binary);std::string initial{std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};check(!initial.empty()&&initial.back()=='\n',"initial mock journal");initial.pop_back();const auto at=initial.find_last_of('\t');std::string chain=initial.substr(at+1);
  std::ofstream out(dir+"/ledger.tsv",std::ios::binary|std::ios::app);const std::string detail=hex(std::string(4096,'x'));
  for(uint64_t seq=2;seq<8194;seq++){const auto prefix=std::to_string(seq)+"\tmutation\t"+hex("a")+"\t0\t"+detail+"\t"+chain;chain=Sha256::of(prefix);out<<prefix<<'\t'<<chain<<'\n';}out.close();
  check(fs::file_size(dir+"/ledger.tsv")>64*1024*1024,"large provided journal fixture did not cross old cap");
  auto r=DurableMockBudget::inspect(dir,cfg);check(r.state.counts.at("requests")==1&&r.state.counts.at("rows")==0&&!r.execution_authorized&&r.status.find("UNCLEAN")==0,"provided raw journal became execution authority");
 });
 std::cout<<"{\"status\":\"CPU_MOCK_IPC_PASS\",\"groups\":"<<groups<<",\"one_global_ledger_per_case\":true,\"native_authority\":false,\"backend_init\":0,\"model_creation\":0,\"native_contexts\":0,\"placements\":0,\"forwards\":0}\n";return 0;
 }catch(const std::exception&e){std::cerr<<"CPU_MOCK_IPC_FAIL: "<<e.what()<<'\n';return 1;}}
